/* 已固化：2026-09-02 晚间修改包（P9–P28） */
window.PACKAGED_PAGE_OVERRIDES = Object.assign(window.PACKAGED_PAGE_OVERRIDES || {}, {"9":"\n      <div class=\"leap-layout\">\n        <div class=\"leap-head\">\n          <div>\n            <div class=\"eyebrow editable\">Part A · 四次真实升级</div>\n            <h1 class=\"slide-title editable\">系统不是设计出来的，<br>而是在四次真实摩擦中长出来的</h1>\n          </div>\n          <p class=\"claim-side editable\">系统成熟不是功能堆叠：每解决一个真实摩擦，才补一层可复用机制。</p>\n        </div>\n        <div class=\"leap-track\">\n          <article class=\"leap-node\">\n            <span class=\"leap-date editable\">03 / 10</span>\n            <span class=\"leap-friction editable\">痛点：<br>AI 每次从零开始</span>\n            <h3 class=\"editable\">记忆底座</h3>\n            <p class=\"editable\">诊断次日把画像、习惯与纠错写进 记忆文件——系统第一次能记住我是谁。</p>\n          </article>\n          <article class=\"leap-node\">\n            <span class=\"leap-date editable\">04 / 17</span>\n            <span class=\"leap-friction editable\">痛点：<br>有优先级，但判断依据与实际 OKR 脱钩</span>\n            <h3 class=\"editable\">OKR 锚点</h3>\n            <p class=\"editable\">目标独立成文件，早晚自动化首跑<div>——判断优先级第一次有了 OKR 依据。</div></p>\n          </article>\n          <article class=\"leap-node milestone\">\n            <span class=\"leap-date editable\">06 / 18 → 07 / 17</span>\n            <span class=\"leap-friction editable\">痛点：<br>每天手动口述进展，<span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">人是最大摩擦力</span></span></span>\n            <h3 class=\"editable\">自动扫描 &amp; 总结<span class=\"leap-badge\">关键进展</span></h3>\n            <p class=\"editable\"><b>沟通信息工具 自动扫描工作群 &amp; 客户沟通记录 → 自动写入新待办、自动更新进展；</b><div>7/17 首次回填 一周 大量沟通信息。</div></p>\n            <a class=\"leap-link\" href=\"https://github.com/huohuoer/wechat-cli\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>github.com/huohuoer/wechat-cli</a>\n          </article>\n          <article class=\"leap-node current\">\n            <span class=\"leap-date editable\">08 月</span>\n            <span class=\"leap-friction editable\">痛点：<br>迭代了很久，还是会有失效的时刻</span>\n            <h3 class=\"editable\">可诊断 · 可修复</h3>\n            <p class=\"editable\">配置异常 + 任务定义受损；靠日志反推并完成重建。不求完美，只是工具。</p>\n          </article>\n        </div>\n        <div class=\"leap-incident\">\n          <span class=\"small-label accent-text\">8/21 故障实录</span>\n          <p class=\"editable\">出差期间自动化静默失效：配置异常、任务定义受损。<strong>靠日志反推故障窗口并补跑流程——系统坏了，记录还在，就能重建。</strong></p>\n        </div>\n      </div>","10":"\n      <div class=\"pipeline-layout\">\n        <div class=\"pipeline-head\">\n          <div>\n            <div class=\"eyebrow editable\">Part A · 每天早上</div>\n            <h1 class=\"slide-title editable\">每天早上：先看全貌，<br>再决定今天真正做什么</h1>\n          </div>\n          <p class=\"claim-side editable\">AI 先给全貌和优先级建议，人再决定今天真正做什么。</p>\n        </div>\n        <div class=\"pipeline-body\">\n          <div class=\"pipeline-left\">\n            <div class=\"flow-rail\">\n              <div class=\"rail-phase\">\n                <div class=\"rail-phase-head\"><span class=\"rail-time\">08:00</span><strong class=\"editable\">群扫描 · morning</strong><span class=\"rail-tool\">沟通信息工具</span></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\">扫 71 群 &amp; 客户沟通记录 → 粗筛出 <b>a 类对客线索 + b 类四力待办 + 方向信号</b></p><span class=\"rail-src editable\">来源：圈定工作群 &amp; 客户沟通记录（取需随时增改）</span></div></div>\n              </div>\n              <div class=\"rail-phase\">\n                <div class=\"rail-phase-head\"><span class=\"rail-time\">08:30</span><strong class=\"editable\">晨间规划 · Mode I（4 步）</strong></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>读锚点，圈定今天的判断尺子</b></p><span class=\"rail-src editable\">读取：目标文件 四力v2 + Q3 需求待办</span></div></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>合并群扫描产出 + 昨日未完事项 + 参考事项DDL</b></p><span class=\"rail-src editable\">读取：群扫描 morning 提炼 + 昨日 memory 日志</span></div></div>\n                <div class=\"rail-step\"><span class=\"rail-dot lime\"></span><div class=\"rail-body\"><p class=\"editable\"><b>输出今日 3 件事（带四力 / KR 标签）→ 落盘 + Git 推送</b></p><span class=\"rail-src editable\">写入：memory/日期-morning.md</span></div></div>\n              </div>\n            </div>\n          </div>\n          <div class=\"p0-card morning-overview-card\">\n            <div class=\"p0-card-head\"><span class=\"small-label\">8/31 真实产出 · 今日 3 件事</span><span class=\"p0-tag editable\">FROM OKR</span></div>\n            <div class=\"p0-real-list\">\n              <div class=\"p0-real p0\"><div class=\"p0-real-top\"><strong class=\"editable\">P0</strong><span class=\"p0-force editable\"><b>商品力 · 品KR2</b></span></div><p class=\"editable\">金秋节拓品追击（在投品覆盖仅 16%）</p></div>\n              <div class=\"p0-real p0\"><div class=\"p0-real-top\"><strong class=\"editable\">P0</strong><span class=\"p0-force editable\"><b>投放力 · 投KR2</b></span></div><p class=\"editable\">益生菌品类潜力腰客陪跑，复盘报告输出（呜XXX 室 / 每 XX士 ）+ 万 XX 直播间掉量诊断</p></div>\n              <div class=\"p0-real\"><div class=\"p0-real-top\"><strong class=\"editable\">P1</strong><span class=\"p0-force editable\"><b>内容力 · 内KR4</b></span></div><p class=\"editable\">原生内容能力上新 + 实时画面 X 直播覆盖推进</p></div>\n            </div>\n            <div class=\"p0-boundary editable\"><strong><span class=\"hl-lime\">AI 提供全貌与建议</span>，<span class=\"hl-lime\">不替人做最后取舍</span>。</strong><div><span style=\"font-size: clamp(14px, 0.92vw, 16px);\">价值是</span><span class=\"hl-lime\" style=\"font-size: clamp(14px, 0.92vw, 16px);\"><b>避免遗漏</b></span><span style=\"font-size: clamp(14px, 0.92vw, 16px);\">；人可以调整，但能看见调整与目标之间的关系。</span></div></div>\n          </div>\n        </div>\n        <button class=\"output-sample-link\" type=\"button\" data-output-sample=\"assets/shot-morning-planning-output.png\" data-output-title=\"晨间规划 · 实际输出样例\">查看实际输出样例 <span aria-hidden=\"true\">↗</span></button>\n      </div>","11":"\n      <div class=\"compound-layout\">\n        <div class=\"compound-head\">\n          <div>\n            <div class=\"eyebrow editable\">Part A · 每天晚上</div>\n            <h1 class=\"slide-title editable\">每天晚上：自动归档进展，<br>顺手生成明天与汇报的原料</h1>\n          </div>\n          <p class=\"claim-side editable\">晚上把事实写回系统：更新任务、检查遗漏，也为明天与汇报留下证据。</p>\n        </div>\n        <div class=\"compound-body\">\n          <div class=\"compound-left\">\n            <div class=\"flow-rail\">\n              <div class=\"rail-phase\">\n                <div class=\"rail-phase-head\"><span class=\"rail-time\">18:00</span><strong class=\"editable\">群扫描 · evening 模式</strong><span class=\"rail-tool\">沟通信息工具</span></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>扫全天增量 → 完成事项、关键变化、新需求</b></p><span class=\"rail-src editable\">来源：全天工作群 &amp; 客户沟通记录</span></div></div>\n              </div>\n              <div class=\"rail-phase\">\n                <div class=\"rail-phase-head\"><span class=\"rail-time\">21:00</span><strong class=\"editable\">晚间归档 · Mode J（4 步）</strong></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>日志检查：缺了就反推补建</b></p><span class=\"rail-src editable\">读取：规则文件 + git commits + 群扫描 morning/evening</span></div></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>按四力分区更新任务状态与 KR 标签</b></p><span class=\"rail-src editable\">读取：目标文件 四力v2 + Q3 需求待办</span></div></div>\n                <div class=\"rail-step\"><span class=\"rail-dot\"></span><div class=\"rail-body\"><p class=\"editable\"><b>回写群扫描 evening 的 b 类进展 + 新需求 DDL</b></p><span class=\"rail-src editable\">写入：Q3 需求待办（四力归类）</span></div></div>\n                <div class=\"rail-step\"><span class=\"rail-dot lime\"></span><div class=\"rail-body\"><p class=\"editable\"><b>生成明日清单 → Git 推送 + J-1/J-2/J-3 校验</b></p><span class=\"rail-src editable\">校验：完成态 / 明日高优 / 新需求追 DDL</span></div></div>\n              </div>\n            </div>\n          </div>\n          <div class=\"compound-right\">\n            <div class=\"reuse-case\">\n              <span class=\"small-label accent-text\">复用案例 · 双周报 3.0</span>\n              <p class=\"editable\">同一份日志，直接喂给<b>「双周报 3.0」Skill</b>——<strong>不用再从零回忆两周做了什么</strong>。</p>\n              <div class=\"case-flow\">\n                <div class=\"case-node editable\"><b>读原料</b>近两周 memory 日志 + 群扫描提炼</div>\n                <div class=\"case-arrow\">↓</div>\n                <div class=\"case-node editable\"><b>按标签归类</b>四力 / KR 标签自动对齐双周报矩阵</div>\n                <div class=\"case-arrow\">↓</div>\n                <div class=\"case-node accent editable\"><b>自动成稿</b>填入双周报 3.0「todo / 工作进展」列</div>\n              </div>\n              <div class=\"reuse-tri editable\"><strong>短期</strong>明日直接接续 · <strong>中期</strong>双周报/月报按标签回收 ·&nbsp;<div><strong>长期</strong>本场分享与 CDG 提报关键数字<span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>全部检索自日志，不靠回忆</b></span></div></div>\n            </div>\n          </div>\n        </div>\n        <button class=\"output-sample-link\" type=\"button\" data-output-sample=\"assets/shot-evening-scan-output.png\" data-output-title=\"群扫描 · 晚间实际输出样例\">查看实际输出样例 <span aria-hidden=\"true\">↗</span></button>\n      </div>","12":"\n      <div class=\"part-summary-layout\">\n        <div class=\"part-summary-head\">\n          <div>\n            <div class=\"eyebrow editable\" contenteditable=\"false\">Part A · 这一部分带走什么</div>\n            <h1 class=\"slide-title editable\" contenteditable=\"false\">AI 不只是列清单，<br>更要让工作不漏事、不偏航、能累积和复用</h1>\n          </div>\n          <p class=\"claim-side editable\" contenteditable=\"false\">人保留目标、边界与最后判断；<div>AI 承担记忆、整理和持续传递。</div></p>\n        </div>\n        <div class=\"summary-loop\">\n          <article><span>01</span><strong class=\"editable\" contenteditable=\"false\">OKR 定方向</strong><p class=\"editable\" contenteditable=\"false\">所有优先级有同一锚点</p></article><i>→</i>\n          <article><span>02</span><strong class=\"editable\" contenteditable=\"false\">信息自动进入</strong><p class=\"editable\" contenteditable=\"false\"><b>减少手动口述与遗漏🌟</b><b>🌟</b></p></article><i>→</i>\n          <article><span>03</span><strong class=\"editable\" contenteditable=\"false\">晨间看全貌</strong><p class=\"editable\" contenteditable=\"false\">由人完成当天取舍<b>🌟</b></p></article><i>→</i>\n          <article><span>04</span><strong class=\"editable\" contenteditable=\"false\">晚间写回</strong><p class=\"editable\" contenteditable=\"false\">让明天与汇报直接复用</p></article>\n        </div>\n        <div class=\"summary-values\">\n          <div class=\"editable\" contenteditable=\"false\"><strong>不遗漏</strong><span>信息与待办有入口</span></div>\n          <div class=\"editable\" contenteditable=\"false\"><strong>不偏航</strong><span>每天都能看见核心目标</span></div>\n          <div class=\"editable\" contenteditable=\"false\"><strong>可复用</strong><span>做过的事不再从零回忆</span></div>\n        </div>\n        <div class=\"summary-transition editable\" contenteditable=\"false\">Part A 先建立目标、上下文与纠错机制 → Part B 把这套机制带进真实客户业务，让人专注问题定义与策略判断</div>\n      </div>","13":"\n      <div class=\"four-forces-layout\">\n        <div class=\"four-forces-head\">\n          <div>\n            <div class=\"eyebrow editable\">Part B · 四力全景</div>\n            <h1 class=\"slide-title editable\">客户的四个问题没变，<br>变化的是我们能回答多深</h1>\n          </div>\n          <p class=\"claim-side editable\">商品、内容、经营和投放不是四个独立工具，而是同一个经营目标下的四个连续问题。</p>\n        </div>\n        <div class=\"force-pair-matrix\">\n          <aside class=\"perspective-rail\" aria-label=\"两种业务视角\">\n            <div class=\"perspective-label customer\"><span>客户视角</span><strong class=\"editable\">客户在问什么？</strong></div>\n            <div class=\"perspective-shift\" aria-hidden=\"true\">↓</div>\n            <div class=\"perspective-label advertising\"><span>广告视角</span><strong class=\"editable\">我们怎样回答？<br><br>（AI 介入前）</strong></div>\n          </aside>\n          <div class=\"force-pairs\">\n            <article class=\"force-pair\">\n              <div class=\"force-question\"><span class=\"force-power-name editable\">商品力</span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">卖什么商品？</strong></span></p></div>\n              <div class=\"force-pair-arrow\" aria-hidden=\"true\">↓</div>\n              <div class=\"force-answer\"><div class=\"force-answer-copy\"><p class=\"editable\"><b><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">看清大盘的潜力品和爆品</span></b></p><div class=\"force-offerings editable\"><span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span>为商家提供：</span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>-爆品榜单，引导商家跟品</b></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>-针对平台的开品建议</b></span><b></b></div></div><div class=\"effort-line e10\"><strong class=\"editable\">5–10%</strong><i></i></div></div>\n            </article>\n            <article class=\"force-pair\">\n              <div class=\"force-question\"><span class=\"force-power-name editable\">内容力</span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">用什么素材转化？<br>直播话术怎么讲？</strong></span></p></div>\n              <div class=\"force-pair-arrow\" aria-hidden=\"true\">↓</div>\n              <div class=\"force-answer\"><div class=\"force-answer-copy\"><p class=\"editable\"><b><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">提炼跑量内容的共性</span></b></p><div class=\"force-offerings editable\"><span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span>为商家提供：</span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>- 爆量素材洞察、素材制作建议</b></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>- 人货场话术建议</b></span><b></b></div></div><div class=\"effort-line e30\"><strong class=\"editable\">约 30%</strong><i></i></div></div>\n            </article>\n            <article class=\"force-pair\">\n              <div class=\"force-question\"><span class=\"force-power-name editable\">经营力</span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">生意经营如何布局？</strong></span></p></div>\n              <div class=\"force-pair-arrow\" aria-hidden=\"true\">↓</div>\n              <div class=\"force-answer\"><div class=\"force-answer-copy\"><p class=\"editable\"><b><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">经营触点诊断与建议</span></b></p></div><div class=\"effort-line e10\"><strong class=\"editable\">5–10%</strong><i></i></div></div>\n            </article>\n            <article class=\"force-pair focus\">\n              <div class=\"force-question\"><span class=\"force-power-name editable\">投放力</span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">怎么投放，投产好且拿量？</strong></span></p></div>\n              <div class=\"force-pair-arrow\" aria-hidden=\"true\">↓</div>\n              <div class=\"force-answer\"><div class=\"force-answer-copy\"><p class=\"editable\"><b><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">投放工具使用策略与建议</span></b></p><div class=\"force-offerings editable\"><span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span>为商家提供：</span></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>- 产品能力使用指引</b></span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><b>- 流量位 / 能力策略</b></span><b></b></div></div><div class=\"effort-line e60\"><strong class=\"editable\">50–60%</strong><i></i></div></div>\n            </article>\n          </div>\n        </div>\n        <div class=\"forces-close editable\">因此，AI 介入工作流，<b>先从最结构化的投放力切入</b>，再展开内容力、经营力与商品力，最后回到整体整合。</div>\n      </div>","14":"\n      <div class=\"capability-layout capability-v3\">\n        <div class=\"capability-head\">\n          <div>\n            <div class=\"eyebrow editable\">Part B · 投放力全貌</div>\n            <h1 class=\"slide-title editable\">两种 AI 优势，<br>支撑投放应用逐层做深</h1>\n          </div>\n          <p class=\"claim-side editable\">计算力让分析跑得更快、更全；业务理解力让判断标准能够持续沉淀和复用。</p>\n        </div>\n        <section class=\"ai-advantage-band\">\n          <div class=\"capability-band-label editable\">AI 能力 · 两大本质优势</div>\n          <div class=\"ai-advantages\">\n            <article class=\"ai-advantage-card compute\">\n              <span class=\"ai-advantage-no\">01</span>\n              <div><h3 class=\"editable\">极致的数据计算力</h3><p class=\"editable\">多源取数、维度切换、交叉验证与大表清洗<div>复盘从人工 4–5 小时压缩到约 10 分钟，分析维度从 3–5 维扩展到 13 维</div></p></div>\n            </article>\n            <article class=\"ai-advantage-card knowledge\">\n              <span class=\"ai-advantage-no\">02</span>\n              <div><h3 class=\"editable\">可被教会的业务理解力</h3><p class=\"editable\">把指标口径、ROI 出价逻辑、链路特性和归因边界写成 Rule<div>让 AI 逐步具备一线运营的判断标准</div></p></div>\n            </article>\n          </div>\n        </section>\n        <div class=\"capability-derive editable\"><span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">能力叠加</strong></span></span></span><i>↓</i><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><i></i><strong>从稳定执行，走向灵活判断与新方法共创</strong></span></span></span><strong></strong></div>\n        <section class=\"application-growth\">\n          <div class=\"capability-band-label editable\">应用逻辑 · 三层递进</div>\n          <div class=\"application-ladder\">\n            <article class=\"application-step level-1\">\n              <div class=\"application-step-top\"><span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">01</span></span></span><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">基础层 · 稳定重复</strong></span></span></span></span></em></div>\n              <h3 class=\"editable\">阶段 1｜常规分析场景沉淀为&nbsp;<span style=\"letter-spacing: -0.02em;\">Skill</span></h3>\n              <p class=\"editable\">梳理工作中高频分析场景，固化成框架清楚、可以验收的标准流程。<div><b><br></b><div>-&nbsp;<span style=\"text-wrap-mode: initial;\">客户复盘</span></div><div><span style=\"text-wrap-mode: initial;\">- 当天掉量排查</span></div><div><span style=\"text-wrap-mode: initial;\">- 日报/周报/月报</span></div></div></p>\n              <div class=\"application-key editable\"><b>能力落点</b>业务规则可沉淀，重复任务可稳定执行</div>\n            </article>\n            <i class=\"application-arrow\">→</i>\n            <article class=\"application-step level-2\">\n              <div class=\"application-step-top\"><span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">02</span></span></span><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">调用层 · 灵活适配</strong></span></span></em></div>\n              <h3 class=\"editable\"><span style=\"letter-spacing: -0.02em;\">阶段 2｜</span>单客户的灵活调用</h3>\n              <p class=\"editable\">沿用同一套 Skill，但根据客户阶段、数据规模和主要矛盾，重新组合维度并判断真正的问题。<div><b><br></b><div></div><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><div></div><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><div>- 头部存量客户：精细化复盘诊断</div><div>- 腰部客户：对齐头部，看清差距</div><div>- 新进潜客：余额/广告基建</div></span><div></div></span><div></div></div></p>\n              <div class=\"application-key editable\"><b>能力落点</b>计算框架可复用，分析问题随客户而变</div>\n            </article>\n            <i class=\"application-arrow\">→</i>\n            <article class=\"application-step level-3\">\n              <div class=\"application-step-top\"><span>03</span><em class=\"editable\">共创层 · 生成新方法</em></div>\n              <h3 class=\"editable\">阶段 3｜深度应用</h3>\n              <p class=\"editable\"><b>人定义业务痛点、分析维度与验收标准；AI 前置处理复杂计算，共同长出新的分析方法。</b><div><br></div><div>- 全行业高潜爆品一览</div><div>- 围绕新痛点新想法展开实践</div></p>\n              <div class=\"application-key editable\"><b>能力落点</b>极致计算力 × 业务理解力，产出新洞察</div>\n            </article>\n          </div>\n        </section>\n      </div>","15":"\n      <div class=\"five-steps-layout\">\n        <div class=\"five-steps-head\">\n          <div>\n            <div class=\"eyebrow editable\">投放力 · 阶段一：流程化</div>\n            <h1 class=\"slide-title editable\">Skill 的门槛不是写 Prompt，<br>而是「有经验」并且能说清楚</h1>\n          </div>\n          <p class=\"claim-side editable\">工作经验是原料，人工验收是终点，也是下一轮迭代的起点。</p>\n        </div>\n        <div class=\"five-steps-body\">\n          <div class=\"steps-column\">\n            <div class=\"step-row\"><span class=\"step-num\">01</span><div><strong class=\"editable\">从重复工作切入</strong><p class=\"editable\">- 客户复盘、日报、周报、月报：<div>- 高频、有框架、结果能验收。</div></p></div></div>\n            <div class=\"step-row key\"><span class=\"step-num\">02</span><div><strong class=\"editable\">先梳理自己的分析逻辑 <em class=\"step-badge editable\">最依赖经验</em></strong><p class=\"editable\"><div><span style=\"text-wrap-mode: initial;\">- 明确分析目标、展开维度、判断口径</span></div><div><span style=\"text-wrap-mode: initial;\">- 语音输入法是 AI 时代最好的伙伴！👍</span></div></p></div></div>\n            <div class=\"step-row key\"><span class=\"step-num\">03</span><div><strong class=\"editable\">喂业务知识，磨合成 Skill <em class=\"step-badge editable\">允许出错</em></strong><p class=\"editable\">- 把客观知识、计算规则和纠错持续写回，让下一次不再重犯。<div>- 要有耐心，问题一定会出现</div></p></div></div>\n            <div class=\"step-row key\"><span class=\"step-num\">04</span><div><strong class=\"editable\">人工验收并反哺 <em class=\"step-badge editable\">判断不可替代</em></strong><p class=\"editable\">- 不同客户要的结论与可用性不同；在多次使用中扩展skill<div>- 人决定取舍，并把经验写回规则。</div><div>-&nbsp;<span style=\"text-wrap-mode: initial;\">明确</span><b style=\"text-wrap-mode: initial;\">最终交付标准</b><b style=\"text-wrap-mode: initial;\">，人的判断很重要！🔴</b></div></p></div></div>\n          </div>\n          <div class=\"correction-card\">\n            <div class=\"correction-head\"><span class=\"small-label\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">验收拦下的真实案例 · 某客户 2/27</span></span></span><span class=\"diag-date editable\">掉量 -25%</span></div>\n            <div class=\"correction-flow\">\n              <div class=\"correction-step wrong\">\n                <span class=\"correction-tag editable\">V1 误判</span>\n                <p class=\"editable\">AI 首版结论：「素材疲劳」导致 CTR 下降</p>\n              </div>\n              <div class=\"correction-step check\">\n                <span class=\"correction-tag editable\">验收重算</span>\n                <p class=\"editable\">根据版位下钻重算后发现 CTR 与 CVR 都在改善；真正变化来自 CPM 345→401。</p>\n              </div>\n              <div class=\"correction-step fixed\">\n                <span class=\"correction-tag editable\">反哺规则</span>\n                <p class=\"editable\">把「先校验版位结构」写入规则，并升级为输出前强制检查。</p>\n              </div>\n            </div>\n            <div class=\"correction-close editable\">人工验收不是末端检查，而是 Skill 持续变准的学习入口。</div>\n          </div>\n        </div>\n      </div>","16":"\n      <div class=\"compare-flow-layout\">\n        <div class=\"compare-flow-head\">\n          <div>\n            <div class=\"eyebrow editable\">投放力 · 阶段二：同框架，不同问题</div>\n            <h1 class=\"slide-title editable\">框架搭好以后，真正拉开差距的<br>是人的灵活改造</h1>\n          </div>\n          <p class=\"claim-side editable\">AI 会沿框架执行；人要根据数据规模、客户阶段和主要矛盾，决定它这次该看什么。</p>\n        </div>\n        <div class=\"stage3-strip\">\n          <div class=\"stage3-label editable\" data-user-scale=\"110\" style=\"font-size: 110%;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">同一框架 ≠ 同一答案</span></span></span></div>\n          <div class=\"stage3-flow\"><span class=\"stage3-step editable\"><strong class=\"user-bold-adjustment\">数据规模</strong></span><i><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">×</span></span></span></i><span class=\"stage3-step editable\"><strong class=\"user-bold-adjustment\">客户阶段</strong></span><i><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">×</span></span></span></i><span class=\"stage3-step editable\"><strong class=\"user-bold-adjustment\">主要矛盾</strong></span><i><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">→</span></span></span></i><span class=\"stage3-step accent editable\">人重新定义问题与优先级</span></div>\n        </div>\n        <div class=\"compare-cards\">\n          <article class=\"client-card\">\n            <div class=\"client-card-head\"><span class=\"client-stage editable\">头部客户</span><h3 class=\"editable\">诺XX德</h3></div>\n            <p class=\"client-q editable\"><b>30+ 直播间 · 近 10 个品线 · 投放链路极复杂</b></p>\n            <p class=\"client-a editable\">人工不可能把数据看齐；AI 先按链路与品线理清全貌，人再判断下一步增长结构。</p>\n            <div class=\"shot-frame client-shot\"><img src=\"assets/shot-ntld-review.png\" alt=\"某品牌直播链路深度分析截图\" loading=\"lazy\"></div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开复盘报告</a>\n          </article>\n          <article class=\"client-card\">\n            <div class=\"client-card-head\"><span class=\"client-stage new editable\">新客户</span><h3 class=\"editable\">某客户</h3></div>\n            <p class=\"client-q editable\"><b>潜力新客 · 直播间 CVR 仅为竞品的三分之一</b></p>\n            <p class=\"client-a editable\">通用 Skill 会建议多搭基建；人的判断是先修直播转化，再考虑堆账户与广告。</p>\n            <div class=\"shot-frame client-shot\"><img src=\"assets/shot-mrdoctor-diagnosis.png\" alt=\"每日博士竞价全景诊断核心结论与对标表\" loading=\"lazy\"></div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开竞价诊断</a>\n          </article>\n        </div>\n      </div>","17":"\n      <div class=\"stage3-layout\">\n        <div class=\"stage3-head\">\n          <div>\n            <div class=\"eyebrow editable\">投放力 · 阶段三：复杂场景洞察</div>\n            <h1 class=\"slide-title editable\">深度应用的价值，是和 AI 一起<br>长出新的分析思路</h1>\n          </div>\n          <p class=\"claim-side editable\">人定义要看懂什么，AI 前置处理复杂计算；已有业务知识越扎实，共创新应用的空间越大。</p>\n        </div>\n        <div class=\"stage3-evidence\">\n          <div class=\"stage3-questions\">\n            <span class=\"small-label\">一份报告前置回答四类复杂问题</span>\n            <article><strong class=\"editable\">哪个行业在涨？</strong><p class=\"editable\">跨行业、链路识别环比增长与增量。</p></article>\n            <article><strong class=\"editable\">什么品类和商品在涨？</strong><p class=\"editable\">从客户与主推商品定位机会形态。</p></article>\n            <article><strong class=\"editable\">打的是谁、什么功效？</strong><p class=\"editable\">把目标人群、用户画像与解决痛点放在同一行看。</p></article>\n            <article><strong class=\"editable\">什么素材证明它在爆量？</strong><p class=\"editable\">直接关联 Top 素材，验证趋势背后的内容表达。</p></article>\n          </div>\n          <figure class=\"stage3-figure\">\n            <div class=\"shot-frame stage3-shot\"><img src=\"assets/shot-delivery-stage3.png\" alt=\"爆品情报周报模块五高潜爆品明细视图\" loading=\"lazy\"></div>\n            <figcaption><span class=\"editable\">模块五 · 高潜爆品明细视图</span><a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开完整周报</a></figcaption>\n          </figure>\n        </div>\n        <div class=\"stage3-close editable\">这份周报只是一个案例：先把业务知识沉淀清楚，新的业务痛点就能变成人与 AI 共同创造的新应用。</div>\n      </div>","18":"\n      <div class=\"evidence-layout\">\n        <div class=\"evidence-head\">\n          <div>\n            <div class=\"eyebrow editable\">投放力 · 从方法分享到平台资产</div>\n            <h1 class=\"slide-title editable\">先分享方法，<br>再把成熟能力沉淀成平台资产</h1>\n          </div>\n          <p class=\"claim-side editable\">先让人理解方法，再把真实业务验证过的能力沉淀为团队与平台资产。</p>\n        </div>\n        <div class=\"spill-track\">\n          <article class=\"spill-node has-shot\">\n            <span class=\"leap-date editable\">02 / 27</span>\n            <h3 class=\"editable\">授人以渔</h3>\n            <p class=\"editable\">第一版 Skill 压缩包 + 实践指南：让没有编程背景的人也能开始，并学会判断与纠偏。</p>\n            <div class=\"shot-frame small spill-shot\"><img src=\"assets/shot-skill-guide.png\" alt=\"CodeBuddy Skill 实践指南截图\" loading=\"lazy\"></div>\n            <a class=\"case-link\" href=\"https://doc.weixin.qq.com/doc/w3_AGYAPQbmACgCNtYqlj4dWR3qzIhfw?scode=AJEAIQdfAAora6fo54AGYAPQbmACg\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>打开实践指南</a>\n          </article>\n          <article class=\"spill-node has-shot\">\n            <span class=\"leap-date editable\">05 / 12</span>\n            <h3 class=\"editable\">能力平台 会客厅</h3>\n            <p class=\"editable\">平台内分享：分析思路与人机分工，让更多同学理解分析方法。</p>\n            <div class=\"shot-frame small spill-shot\"><img src=\"assets/shot-adataclaw-sharing.png\" alt=\"能力平台 Claw 分享页封面\" loading=\"lazy\"></div>\n            <a class=\"case-link\" href=\"https://going0917.github.io/adataclaw-sharing/\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>打开分享页</a>\n          </article>\n          <article class=\"spill-node has-shot\">\n            <span class=\"leap-date editable\">成熟后</span>\n            <h3 class=\"editable\">平台化输出</h3>\n            <p class=\"editable\">成熟 Skill 上架平台，成为可直接调用的预制能力。</p>\n            <div class=\"shot-frame small spill-shot\"><img src=\"assets/shot-adata-marketplace.png\" alt=\"能力平台 Skill 市集上架截图\" loading=\"lazy\"></div>\n          </article>\n        </div>\n        <div class=\"value-cards\">\n          <article class=\"value-card\">\n            <span class=\"small-label\">效率</span>\n            <strong class=\"editable\">4–5h → 约 10min</strong>\n            <p class=\"editable\">单客户复盘</p>\n          </article>\n          <article class=\"value-card\">\n            <span class=\"small-label\">深度</span>\n            <strong class=\"editable\">3–5 维 → 13 维</strong>\n            <p class=\"editable\">按需拉通的分析维度</p>\n          </article>\n          <article class=\"value-card\">\n            <span class=\"small-label\">外溢</span>\n            <strong class=\"editable\">20+ 客户 · 300+ 报告 · 多项 Skill 上架</strong>\n            <p class=\"editable\">从个人方法走向可复用资产</p>\n          </article>\n        </div>\n        <div class=\"evidence-close editable\">投放解决「投得准、跑得稳」；用户被触达之后，真正完成转化的是内容。下一页把同一套方法带进素材与直播。</div>\n      </div>","19":"\n      <div class=\"cf-layout\">\n        <div class=\"cf-head\">\n          <div>\n            <div class=\"eyebrow editable\">内容力 · 为什么是现在</div>\n            <h1 class=\"slide-title editable\">内容力：AI 的天然战场，是把「什么是好内容」<br>定义成可分析的框架</h1>\n          </div>\n          <p class=\"claim-side editable\">先把「什么是好内容」定义成框架，<span style=\"text-wrap-mode: initial;\">再让 AI 跑全量；素材与直播使用同一套方法。</span></p>\n        </div>\n        <div class=\"cf-scenes\">\n          <article class=\"cf-scene\">\n            <div class=\"cf-scene-head\"><h3 class=\"editable\">广告素材</h3><span class=\"cf-scene-meta editable\">15–60 秒短视频</span></div>\n            <p class=\"cf-scene-essence editable\">本质：一段音视频的转化效率</p>\n            <span class=\"cf-insight-label editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">痛点 · 人工判断难以规模化</span></strong></span></span></span>\n            <div class=\"cf-scene-pains\">\n              <span class=\"editable\">每个人看的重点不同</span><span class=\"editable\">易遗漏</span><span class=\"editable\">耗费人力、难以高频</span><span class=\"editable\">依赖单人经验、不够全面</span>\n            </div>\n          </article>\n          <article class=\"cf-scene\">\n            <div class=\"cf-scene-head\"><h3 class=\"editable\">直播间</h3><span class=\"cf-scene-meta editable\">3–30 分钟长视频</span></div>\n            <p class=\"cf-scene-essence editable\">本质：一段更长、更复杂的音视频</p>\n            <span class=\"cf-insight-label editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">痛点 · 人力不足以支撑直播间诊断</span></span></span></span>\n            <div class=\"cf-scene-pains\">\n              <span class=\"editable\">内容漫长、无限延伸</span><span class=\"editable\">平台无法直接拉取</span><span class=\"editable\">诊断频率极低</span><span class=\"editable\">我们本身没那么懂直播经营</span>\n            </div>\n          </article>\n        </div>\n        <div class=\"cf-aivalue\">\n          <span class=\"small-label\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">框架提炼 · AI 的介入方式不是直接给结论</span></span>\n          <div class=\"cf-aivalue-flow\">\n            <span class=\"cf-av-step editable\"><strong class=\"user-bold-adjustment\">人先定义「什么是好内容」的框架</strong><br><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">我负责的健康食品的赛道素材核心：<span class=\"late-inline-highlight\">目标对象痛点挖掘 + 信任力构建</span></strong></span></span></em></span>\n            <i>→</i>\n            <span class=\"cf-av-step accent editable\">AI 按框架拆解全量音视频<br><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">频率 · 深度 · 全面性，三重提升</span></em></span>\n          </div>\n        </div>\n        <div class=\"cf-guide editable\">接下来两条线展开：素材线（赛道底座 → 单客户与节点延展）+直播间线（人货场底座 → 诊断与场景赋能）</div>\n      </div>","20":"\n      <div class=\"content-journey-layout\">\n        <div class=\"content-journey-head\">\n          <div>\n            <div class=\"eyebrow editable\">内容力 · 素材三层演进</div>\n            <h1 class=\"slide-title editable\">同一套素材框架，三层递进</h1>\n          </div>\n          <p class=\"claim-side editable\">同一套内容框架逐层做深：看得全 → 看得准 → 做得前。</p>\n        </div>\n        <div class=\"content-journey-grid\">\n          <article class=\"content-stage stage-foundation\">\n            <div class=\"content-stage-top\"><span>01</span><em class=\"editable\">L1 · 赛道底座</em></div>\n            <h3 class=\"editable\">提炼赛道共性</h3>\n            <p class=\"content-stage-role editable\">看得全</p>\n            <div class=\"shot-frame content-stage-shot\"><img src=\"assets/shot-cf-track-common.png\" alt=\"赛道爆量素材五大共性特征与素材类型矩阵\" loading=\"lazy\"></div>\n            <div class=\"content-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">赛道好内容有哪些共性？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去服务</span></b><p class=\"editable\">人工抽样看片，标准不一且容易遗漏。</p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">AI 核心增益</span></b><p class=\"editable\">Top 素材 × 9大 品类全量逐帧，提炼 5 大跑量共性。</p></section>\n            </div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开赛道拆解报告</a>\n          </article>\n          <article class=\"content-stage stage-diagnosis\">\n            <div class=\"content-stage-top\"><span>02</span><em class=\"editable\">L2 · 诊断跃迁</em></div>\n            <h3 class=\"editable\">单客户诊断</h3>\n            <p class=\"content-stage-role editable\">看得准</p>\n            <div class=\"shot-frame content-stage-shot\"><img src=\"assets/shot-cf-wonderlab.png\" alt=\"某品牌益生菌素材深度分析：五品牌核心指标对比\" loading=\"lazy\"></div>\n            <div class=\"content-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">同品类的竞品怎么做？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去服务</span></b><p class=\"editable\"><div><span style=\"text-wrap-mode: initial;\">依赖经验看片，很难定位具体流失节点。</span></div></p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">AI 核心增益</span></b><p class=\"editable\">逐帧拆解 + 指标对照，定位流失并下钻品类复用。</p></section>\n            </div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开某品牌深度分析</a>\n          </article>\n          <article class=\"content-stage stage-forward\">\n            <div class=\"content-stage-top\"><span>03</span><em class=\"editable\">L3 · 前置跃迁</em></div>\n            <h3 class=\"editable\">营销节点构建</h3>\n            <p class=\"content-stage-role editable\">做得前</p>\n            <div class=\"shot-frame content-stage-shot\"><img src=\"assets/shot-cf-duoyanshou-node.png\" alt=\"多燕瘦三伏天节点 P0 建议卡：问题诊断/优化方向/AB测试/口播钩子\" loading=\"lazy\"></div>\n            <div class=\"content-stage-detail\">\n              <section><b class=\"editable\"><br><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>客户需求</span></b><p class=\"editable\">节点到来前，内容该怎么准备？</p></section>\n              <section class=\"before\"><b class=\"editable\"><br><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>过去服务</span></b><p class=\"editable\">给一些宽泛的制作建议</p></section>\n              <section class=\"after\"><b class=\"editable\"><br><br><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">AI 核心增益</span></b><p class=\"editable\"><div><span style=\"text-wrap-mode: initial;\">场景 × TA × 客户优势重组，输出诊断与口播钩子。</span></div></p></section>\n            </div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开三伏天节点报告</a>\n          </article>\n        </div>\n        <div class=\"content-journey-close editable\"><strong>深度来自对客户诉求的理解；AI 让每一层都能规模化执行。</strong><span>下一页把同一套逻辑带进更长、更难的直播间。</span></div>\n      </div>","21":"\n      <div class=\"livebase-layout\">\n        <div class=\"livebase-head\">\n          <div>\n            <div class=\"eyebrow editable\">内容力 · 直播间分析</div>\n            <h1 class=\"slide-title editable\">同一套逻辑，换一个更长、<br>更难的分析场景</h1>\n          </div>\n          <p class=\"claim-side editable\">人先定义人货场框架，AI 再跑全量样本，最终沉淀成赛道可复用的方法论。</p>\n        </div>\n        <div class=\"livebase-body\">\n          <div class=\"livebase-left\">\n            <div class=\"bridge-card\">\n              <span class=\"small-label\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">与素材页相同的逻辑，两个变化</span></span></span></span></span></span>\n              <div class=\"bridge-row\"><span class=\"bridge-from editable\">素材：15–60 秒 · 痛点 + 信任</span><i>→</i><span class=\"bridge-to editable\">直播间：3–30 分钟 · 人货场 + 话术</span></div>\n            </div>\n            <div class=\"livebase-framework\">\n              <span class=\"small-label\">直播间的框架怎么定（含赛道行业化特点）</span>\n              <div class=\"fw-grid\">\n                <div class=\"fw-cell\"><strong class=\"editable\">人</strong><span class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><strong class=\"user-bold-adjustment\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">主播状态与人设</span></span></span></strong></span></span></div>\n                <div class=\"fw-cell\"><strong class=\"editable\">货</strong><span class=\"editable\"><strong class=\"user-bold-adjustment\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">货品设计与塑品</span></span></span></strong></span></div>\n                <div class=\"fw-cell\"><strong class=\"editable\">场</strong><span class=\"editable\"><strong class=\"user-bold-adjustment\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">场景与氛围</span></span></span></strong></span></div>\n                <div class=\"fw-cell\"><strong class=\"editable\">话术</strong><span class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><strong class=\"user-bold-adjustment\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">痛点挖掘 · 逼单循环</span></span></span></span></strong></span></span></span></span></span></span></span></span></span></span></span></div>\n              </div>\n            </div>\n            <div class=\"livebase-pains compact\">\n              <span class=\"pain-chip editable\">平台拉不到内容</span>\n              <span class=\"pain-chip editable\">诊断频率极低</span>\n              <span class=\"pain-chip editable\">不懂直播经营</span>\n            </div>\n          </div>\n          <div class=\"livebase-result\">\n            <div class=\"livebase-stats\">\n              <div><strong class=\"editable\">14</strong><span class=\"editable\">头部直播间</span></div>\n              <div><strong class=\"editable\">228</strong><span class=\"editable\">关键帧</span></div>\n              <div><strong class=\"editable\">17 份 · 98%</strong><span class=\"editable\">音频转写与准确率</span></div>\n            </div>\n            <div class=\"livebase-method\">\n              <span class=\"small-label\">沉淀 · 赛道 CVR 人货场方法论</span>\n              <ul>\n                <li class=\"editable\">四大人设类型</li>\n                <li class=\"editable\">单品聚焦是 CVR 最高的挂车策略</li>\n                <li class=\"editable\">品类定制场景五要素</li>\n                <li class=\"editable\">5–7 分钟标准话术循环</li>\n              </ul>\n            </div>\n            <div class=\"branch-links dark-links\">\n              <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">分析框架文档</a>\n              <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">方法论文档</a>\n            </div>\n          </div>\n        </div>\n        <div class=\"livebase-quote editable\">「第一次看到 AI 跑出来的分析——<b><span class=\"late-quote-highlight\">它不仅帮我理解了赛道商家的打法与信任构建逻辑，更让我沉淀出一套赛道专属方法论，进而帮更多商家做延展。</span></b>」</div>\n      </div>","22":"\n      <div class=\"content-case-layout\">\n        <div class=\"content-case-head\">\n          <div>\n            <div class=\"eyebrow editable\">内容力 · 直播应用延展</div>\n            <h1 class=\"slide-title editable\">从「事后诊断」到「事前预案」</h1>\n          </div>\n          <p class=\"claim-side editable\">方法论只有进入客户动作，才完成闭环：标杆经验变成清单，新场景变成预案。</p>\n        </div>\n        <div class=\"content-case-grid\">\n          <article class=\"content-case-card case-diagnosis\">\n            <div class=\"content-case-top\"><span>01</span><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">事后诊断 · 某客户 8/28</span></span></em></div>\n            <h3 class=\"editable\">单客户对标</h3>\n            <p class=\"content-case-role editable\">从经验到检查清单</p>\n            <div class=\"shot-frame content-case-shot\"><img src=\"assets/shot-live-mrdoctor-script.png\" alt=\"每日博士直播间话术维度核心问题清单\" loading=\"lazy\"></div>\n            <div class=\"content-case-detail\">\n              <section><span style=\"font-weight: normal;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></span></span></span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">这个直播间与标杆差在哪里？</span></p></section>\n              <section class=\"before\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去服务</span></span></span><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">人工深诊成本高，只覆盖少数头部客户。</span></span></span></p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">AI 核心增益</span></b><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">标杆 + 转写逐项对照，生成检查清单。</span></span></span></p></section>\n            </div>\n            <div class=\"content-case-result editable\"><strong>定位根因</strong>：3 段重复话术；最硬证据未口播。<span>当日客户完成复盘，并拆成五类调整动作。</span></div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开诊断报告</a>\n          </article>\n          <article class=\"content-case-card case-forward\">\n            <div class=\"content-case-top\"><span>02</span><em class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">事前规划 · 某营销节点某直播场景</span></span></em></div>\n            <h3 class=\"editable\">特色场景赋能</h3>\n            <p class=\"content-case-role editable\">从复盘到预设方案</p>\n            <div class=\"shot-frame content-case-shot\"><img src=\"assets/shot-live-seaside-script.png\" alt=\"华大某直播场景话术改造诊断与双直播间差异化话术框架\" loading=\"lazy\"></div>\n            <div class=\"content-case-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></span></b><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">新场景开播前，话术和脚本怎么准备？</span></p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去服务</span></span></b><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">临时把平播话术改成适配新场景。</span></p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">AI 核心增益</span></b><p class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">平播资产 × 海边场景，事前生成方案。</span></p></section>\n            </div>\n            <div class=\"content-case-result editable\"><strong>5 个品牌 · 5 份方案</strong><span>并提报产品需求：从事后复盘走向事前规划。</span></div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开华大话术方案</a>\n          </article>\n        </div>\n        <div class=\"content-case-close editable\"><strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">&nbsp; <span class=\"user-font-adjustment\" style=\"font-size: 115%;\">&nbsp;<span class=\"late-inline-highlight\">能力平权化</span></span><span style=\"color: rgba(240, 232, 210, 0.7); font-size: clamp(12px, 0.94vw, 16px);\">：<span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去只有少数头部客户才配得上的深度诊断，现在可以规模化给更多服务对象。</span></span></span></strong><br><span>下一步回到更上游的商品决策：商家究竟该卖什么、开什么品。</span></div>\n      </div>","23":"\n      <div class=\"product-journey-layout\">\n        <div class=\"product-journey-head\">\n          <div>\n            <div class=\"eyebrow editable\">商品力 · 四层服务演进</div>\n            <h1 class=\"slide-title editable\">从「追爆品」到「为单个商家开品」</h1>\n          </div>\n          <p class=\"claim-side editable\">不是四个孤立工具，而是服务价值逐层升级：看见市场 → 建立底座 → 翻译场景 → 支持决策。</p>\n        </div>\n        <div class=\"product-journey-grid\">\n          <article class=\"product-stage stage-baseline\">\n            <div class=\"product-stage-top\"><span>01</span><em class=\"editable\">基础服务 · 无 AI</em></div>\n            <h3 class=\"editable\">广告爆品</h3>\n            <p class=\"product-stage-role editable\"><strong class=\"user-bold-adjustment\">局部市场</strong></p>\n            <div class=\"product-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">什么商品投得好、怎么投、表现如何？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去能交付</span></b><p class=\"editable\">人工整理双周报，提供广告域投放参考。</p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>AI 后新增</span></b><p class=\"editable\">把低频样本升级为后续全域分析的入口。</p></section>\n            </div>\n            <div class=\"product-stage-value editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">价值起点 · 从经验找品到有数据可追</span></div>\n          </article>\n          <article class=\"product-stage stage-data\">\n            <div class=\"product-stage-top\"><span>02</span><em class=\"editable\">1.0 · 数据底座</em></div>\n            <h3 class=\"editable\">全域爆品</h3>\n            <p class=\"product-stage-role editable\"><strong class=\"user-bold-adjustment\">补齐市场</strong></p>\n            <div class=\"product-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">全域卖什么、谁在买、应该怎样选品？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去能交付</span></b><p class=\"editable\">人力只能抽样，无法持续跑全量商品。</p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>AI 核心增益</span></b><p class=\"editable\">采集、清洗、纠错与聚类，形成可持续底座。</p></section>\n            </div>\n            <div class=\"product-stage-value editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">服务升级 · 从广告域走向全域商品机会</span></div>\n          </article>\n          <article class=\"product-stage stage-scene\">\n            <div class=\"product-stage-top\"><span>03</span><em class=\"editable\">2.0 · 场景跃迁</em></div>\n            <h3 class=\"editable\">营销地图</h3>\n            <p class=\"product-stage-role editable\"><strong class=\"user-bold-adjustment\">翻译场景</strong></p>\n            <div class=\"product-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">节点到来时，该卖什么、面向谁、怎么讲？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去能交付</span></b><p class=\"editable\">只有大表，商家仍需自己理解和行动。</p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>AI 核心增益</span></b><p class=\"editable\"><strong class=\"user-bold-adjustment\">把数据翻译成品类、人群、场景与内容策略。</strong></p></section>\n            </div>\n            <div class=\"product-stage-value editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">关键亮点 · 从「有数据」到「会应用」</span></div>\n          </article>\n          <article class=\"product-stage stage-decision\">\n            <div class=\"product-stage-top\"><span>04</span><em class=\"editable\">3.0 · 决策跃迁</em></div>\n            <h3 class=\"editable\">单客开品</h3>\n            <p class=\"product-stage-role editable\"><strong class=\"user-bold-adjustment\">支持决策</strong></p>\n            <div class=\"product-stage-detail\">\n              <section><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">客户需求</span></b><p class=\"editable\">结合自身约束，下一步该开什么品？</p></section>\n              <section class=\"before\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">过去能交付</span></b><p class=\"editable\">通用报告 + 人工定制，首版约需一周。</p></section>\n              <section class=\"after\"><b class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><br>AI 核心增益</span></b><p class=\"editable\">13 字段生成 P0 / P1 路线，<b><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">个性化定制</span></span></span></span></b>。</p></section>\n            </div>\n            <div class=\"product-stage-value editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">决策亮点 · 从行业洞察到单客优先级</span></div>\n          </article>\n        </div>\n        <div class=\"product-journey-close editable\"><strong>递进不是数据越做越多，而是离客户决策越来越近。</strong><span>下一页用四类真实产物逐列验证。</span></div>\n      </div>","24":"\n      <div class=\"product-proof-layout\">\n        <div class=\"product-proof-head\">\n          <div>\n            <div class=\"eyebrow editable\">商品力 · 四层真实产物</div>\n            <h1 class=\"slide-title editable\">同一条演进链，AI 介入后的深度交付</h1>\n          </div>\n          <p class=\"claim-side editable\">每一列都能现场打开；数字用于证明规模，人的判断仍负责最终决策。</p>\n        </div>\n        <div class=\"product-proof-grid\">\n          <article class=\"product-proof-card proof-baseline\">\n            <div class=\"product-proof-top\"><span>01</span><em class=\"editable\">无 AI · 广告域</em></div>\n            <h3 class=\"editable\">广告爆品双周报</h3>\n            <div class=\"shot-frame product-proof-shot\"><img src=\"assets/shot-prod-ad-domain.png\" alt=\"健康滋补爆品及潜力新品周报表格\" loading=\"lazy\"></div>\n            <div class=\"product-proof-copy\">\n              <p><b class=\"editable\">客户要解决</b><span class=\"editable\">什么在投、怎么投、表现如何？</span></p>\n              <p class=\"before\"><b class=\"editable\"><br><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">过去服务</span></span></b><span class=\"editable\">人工整理，低频提供广告域参考。</span></p>\n              <p class=\"after\"><b class=\"editable\"><br>AI 增益</b><span class=\"editable\">为全域扩展建立可比较的起点。<br><br></span></p>\n            </div>\n            <div class=\"product-proof-result editable\"><strong>交付边界</strong>：看得到“投得好”，还看不到“全域卖得好”。</div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开双周报</a>\n          </article>\n          <article class=\"product-proof-card proof-data\">\n            <div class=\"product-proof-top\"><span>02</span><em class=\"editable\">1.0 · 全域底座</em></div>\n            <h3 class=\"editable\">爆品拓品机会榜</h3>\n            <div class=\"shot-frame product-proof-shot\"><img src=\"assets/shot-prod-full-domain.png\" alt=\"食品饮料爆品拓品机会榜工作沟通工具表格\" loading=\"lazy\"></div>\n            <div class=\"product-proof-copy\">\n              <p><b class=\"editable\">客户要解决</b><span class=\"editable\">全域卖什么、谁在买、怎么选品？</span></p>\n              <p class=\"before\"><b class=\"editable\"><br>过去服务</b><span class=\"editable\">人力只能抽样，无法持续跑全量。</span></p>\n              <p class=\"after\"><b class=\"editable\"><br>AI 增益</b><span class=\"editable\">采集、清洗、纠错、聚类与卖点识别。<br><br></span></p>\n            </div>\n            <div class=\"product-proof-result editable\"><strong>多类商品信息</strong> · 4 段业务流 · 3 份报告 + 1 套工具</div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开拓品榜</a>\n          </article>\n          <article class=\"product-proof-card proof-scene\">\n            <div class=\"product-proof-top\"><span>03</span><em class=\"editable\">2.0 · 场景应用</em></div>\n            <h3 class=\"editable\">应季营销地图</h3>\n            <div class=\"shot-frame product-proof-shot\"><img src=\"assets/shot-prod-marketing-map.png\" alt=\"某平台某营销节点应季营销地图五大节点\" loading=\"lazy\"></div>\n            <div class=\"product-proof-copy\">\n              <p><b class=\"editable\">客户要解决</b><span class=\"editable\">节点来了，卖什么、面向谁、怎么讲？</span></p>\n              <p class=\"before\"><b class=\"editable\"><br>过去服务</b><span class=\"editable\">拿到大表，仍要自己理解和行动。</span></p>\n              <p class=\"after\"><b class=\"editable\"><br>AI 增益</b><span class=\"editable\">翻译成品类、人群、场景与内容策略。<br><br></span></p>\n            </div>\n            <div class=\"product-proof-result editable\"><strong>11 类目</strong> · 多类商品 · 多类品牌 · 5 个节点</div>\n            <a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开某营销节点地图</a>\n          </article>\n          <article class=\"product-proof-card proof-decision\">\n            <div class=\"product-proof-top\"><span>04</span><em class=\"editable\">3.0 · 单客决策</em></div>\n            <h3 class=\"editable\">某产品开品报告</h3>\n            <div class=\"product-proof-dual\">\n              <div class=\"shot-frame product-proof-shot\"><img src=\"assets/shot-prod-prompt-gen.png\" alt=\"商家开品洞察提示词生成器四步流程\" loading=\"lazy\"></div>\n              <div class=\"shot-frame product-proof-shot\"><img src=\"assets/shot-prod-tigernut.png\" alt=\"某产品单客开品报告\" loading=\"lazy\"></div>\n            </div>\n            <div class=\"product-proof-copy\">\n              <p><b class=\"editable\">客户要解决</b><span class=\"editable\">结合自身约束，下一步开什么品？</span></p>\n              <p class=\"before\"><b class=\"editable\"><br>过去服务</b><span class=\"editable\">通用洞察 + 人工定制，首版约一周。</span></p>\n              <p class=\"after\"><b class=\"editable\"><br>AI 增益</b><span class=\"editable\">13 字段叠加约束，生成 P0 / P1 路线。<br><br></span></p>\n            </div>\n            <div class=\"product-proof-result editable\"><strong>约 1 周 → 约 5 分钟</strong><span>仅指首版初稿；人终审供应链与品牌匹配。</span></div>\n            <div class=\"product-proof-links\"><a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开生成器</a><a class=\"case-link\" href=\"#\" target=\"_blank\" rel=\"noreferrer\">打开报告</a></div>\n          </article>\n        </div>\n      </div>","25":"\n      <div class=\"integrated-layout\">\n        <div class=\"integrated-head\">\n          <div>\n            <div class=\"eyebrow editable\" contenteditable=\"false\">四力打通 · 同一个经营目标</div>\n            <h1 class=\"slide-title editable\" contenteditable=\"false\">真正的价值不是四个工具，<br>而是一套完整经营方案</h1>\n          </div>\n          <div class=\"client-start\"><strong class=\"editable\" contenteditable=\"false\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\"><span class=\"user-font-adjustment\" style=\"font-size: 87%;\">潜力新客也可以拥有深度全案</span></span></span></span></strong><span class=\"editable\" contenteditable=\"false\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">某海外保健食品客户直播起点；<br>目标不是优化单一指标，而是把营销链路跑起来。</span></span></div>\n        </div>\n        <div class=\"force-table\">\n          <div class=\"force-row header\"><span>模块</span><span><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">人做的事 · 策略判断</span></span></span></span><span>AI 做的事 · 数据整合</span></div>\n          <div class=\"force-row\"><div class=\"force-name editable\" contenteditable=\"false\"><span class=\"force-index\">01</span>商品 / 选品</div><div class=\"force-human editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>决定方向</strong>：选择与客户能力匹配的品类与组合</span></div><div class=\"force-ai editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>交叉验证</strong>：赛道直播跑量品类 × 客户 CID 已验证品类</span></div></div>\n          <div class=\"force-row\"><div class=\"force-name editable\" contenteditable=\"false\"><span class=\"force-index\">02</span>内容 / 素材</div><div class=\"force-human editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>判断迁移</strong>：找到客户素材与头部打法契合的要点</span></div><div class=\"force-ai editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>逐条拆解</strong>：客户全量素材 × 赛道头部素材，提取共同规律</span></div></div>\n          <div class=\"force-row\"><div class=\"force-name editable\" contenteditable=\"false\"><span class=\"force-index\">03</span>内容 / 直播</div><div class=\"force-human editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>选择标杆</strong>：明确该追赶谁、差距在哪里</span></div><div class=\"force-ai editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>批量分析</strong>：多场标杆直播，提炼人货场与话术标杆</span></div></div>\n          <div class=\"force-row\"><div class=\"force-name editable\" contenteditable=\"false\"><span class=\"force-index\">04</span>投放链路</div><div class=\"force-human editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>定义顺序</strong>：决定版位、智投和工具组合的突破优先级</span></div><div class=\"force-ai editable\" contenteditable=\"false\"><strong></strong><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong>差距定位</strong>：整合头部客户基建数据，与客户现状逐项对比</span></div></div>\n        </div>\n        <div class=\"integrated-close editable\" contenteditable=\"false\">人负责目标、策略与取舍；AI 负责跨数据源验证、批量拆解和差距定位。</div>\n      </div>","26":"\n      <div class=\"loop-layout\">\n        <div class=\"loop-head\">\n          <div>\n            <div class=\"eyebrow editable\">全篇回收 · 一条能力成长闭环</div>\n            <h1 class=\"slide-title editable\">这套能力为什么会持续变强：<br>对内与对客，共用一条闭环</h1>\n          </div>\n          <p class=\"claim-side editable\">目标与上下文让 AI 不偏航，真实业务持续暴露问题并写回规则；能力因此从一次性交付变成持续生长。</p>\n        </div>\n        <div class=\"loop-chain\">\n          <article><span>01</span><strong class=\"editable\">锚定</strong><p class=\"editable\">OKR 给所有判断一个方向</p></article><i>→</i>\n          <article><span>02</span><strong class=\"editable\">感知</strong><p class=\"editable\">信息自动进入，不靠口述</p></article><i>→</i>\n          <article><span>03</span><strong class=\"editable\">发现</strong><p class=\"editable\"><b>真实业务暴露痛点与错误</b></p></article><i>→</i>\n          <article><span>04</span><strong class=\"editable\">固化</strong><p class=\"editable\">高频问题写成 SKILL / Rule</p></article><i>→</i>\n          <article><span>05</span><strong class=\"editable\">纠错</strong><p class=\"editable\">从「能做」到「稳定做」</p></article><i>→</i>\n          <article><span>06</span><strong class=\"editable\">外溢</strong><p class=\"editable\">团队分享与平台资产</p></article>\n        </div>\n        <div class=\"loop-evidence\">\n          <div class=\"editable\"><strong>约 24 周</strong><span>连续运行</span><span><br></span><span><br></span></div>\n          <div class=\"editable\"><strong>四力</strong><span>真实客户实践</span><span><br></span><span><br></span></div>\n          <div class=\"editable\"><strong>300+</strong><span>份分析报告</span><span><br></span><span><br></span></div>\n          <div class=\"editable\"><strong>平台资产</strong><span><span style=\"color: rgba(240, 232, 210, 0.64);\">成熟 Skill 持续外溢</span></span><span><br></span><span><br></span></div>\n        </div>\n        <div class=\"loop-close editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">人负责目标、 找问题、真伪与取舍；AI 负责记忆、整合、执行与扩散。</span></span></div>\n      </div>","27":"\n      <div class=\"action-layout\">\n        <div class=\"action-head\">\n          <div>\n            <div class=\"eyebrow editable\">行动建议 · 从一个真实痛点开始</div>\n            <h1 class=\"slide-title editable\">如果你也想开始：<br>一个真实痛点 + 三份文件</h1>\n          </div>\n          <p class=\"claim-side editable\">先写目标、日志和红线，再选一个高频且可验收的真实场景，让 AI 连续做三次。</p>\n        </div>\n        <div class=\"action-steps\">\n          <span class=\"action-step editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">写目标</strong></span></span></span></span><i>→</i>\n          <span class=\"action-step editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">记事实</strong></span></span></span></span><i>→</i>\n          <span class=\"action-step editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">写红线</strong></span></span></span></span><i>→</i>\n          <span class=\"action-step editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">选重复场景</strong></span></span></span></span><i>→</i>\n          <span class=\"action-step accent editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\"><strong class=\"user-bold-adjustment\">&nbsp;连续做三次，再把错误写回规则&nbsp;</strong></span></span></span></span>\n        </div>\n        <div class=\"action-roles\">\n          <article class=\"role-card\"><strong class=\"editable\">产研</strong><p class=\"editable\">从需求归类或评审纪要开始</p><span class=\"editable\">验收：分类是否可直接用</span></article>\n          <article class=\"role-card\"><strong class=\"editable\">销售</strong><p class=\"editable\">从客户跟进与方案复盘开始</p><span class=\"editable\">验收：下次拜访能否直接用</span></article>\n          <article class=\"role-card\"><strong class=\"editable\">运营</strong><p class=\"editable\">从日报或复盘开始</p><span class=\"editable\">验收：是否不用再周而复始写材料</span></article>\n          <article class=\"role-card\"><strong class=\"editable\">管理者</strong><p class=\"editable\">从会议参谋和决策记录开始</p><span class=\"editable\">验收：决策依据是否可追溯</span></article>\n        </div>\n        <div class=\"action-close\"><span class=\"editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">这套系统也不是从 25 个 Skill 开始的——而是从一个真实任务与三份文件开始的。</span></span><a class=\"case-link\" href=\"starter-kit.html\" target=\"_blank\" rel=\"noreferrer\">打开三件套模板</a></div>\n      </div>","28":"\n      <div class=\"closing-layout\">\n        <div class=\"closing-main\">\n          <div class=\"eyebrow editable\">最后一句</div>\n          <h1 class=\"closing-quote editable\"><span class=\"user-font-adjustment\" style=\"font-size: 115%;\">OKR 给方向，AI 给杠杆；<br><span class=\"okr-line\">人的经验值得放大，关键判断不可替代。</span></span><span class=\"okr-line\"></span></h1>\n          <p class=\"closing-sub editable\">AI 真正放大的不是任务量，而是<strong class=\"user-bold-adjustment\"><span class=\"late-inline-highlight\">一个人持续判断、沉淀经验并创造新可能的能力</span>。</strong></p>\n        </div>\n        <div class=\"closing-links\">\n          <span class=\"small-label\">会后延伸 · 公开资料与模板</span>\n          <a class=\"case-link\" href=\"starter-kit.html\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>目标 / 日志 / 红线三件套</a>\n          <a class=\"case-link\" href=\"https://going0917.github.io/ai-ops-showcase/\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>运营 × AI 全局架构</a>\n          <a class=\"case-link\" href=\"https://going0917.github.io/ai-ops-showcase/townhall-0518/\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>Townhall 四力实践</a>\n          <a class=\"case-link\" href=\"https://going0917.github.io/adataclaw-sharing/\" target=\"_blank\" rel=\"noreferrer\" data-preserve-external-link>能力平台 Claw 分享</a>\n        </div>\n      </div>"});

